                    adj[a].add(b)
    # Reachable from seeds
    closure = set()
    stack = list(seeds)
    while stack:
        u = stack.pop()
        if u in closure:
            continue
        closure.add(u)
        for w in adj[u]:
            if w not in closure:
                stack.append(w)
    # Connected components within closure
    comps = []
    seen = set()
    for s in sorted(closure):
        if s in seen:
            continue
        comp = []
        q = [s]
        seen.add(s)
        while q:
            u = q.pop()
            comp.append(u)
            for w in adj[u]:
                if w in closure and w not in seen:
                    seen.add(w)
                    q.append(w)
        comps.append(sorted(comp))
    return comps


def brute_feasible(r, available):
    h = len(available)
    # Assign each hole j to None or a row in range(r); unavailable holes must be None.
    choices = [[None] + list(range(r)) if available[j] else [None] for j in range(h)]
    for assign in itertools.product(*choices):
        used_rows = {row for row in assign if row is not None}
        if len(used_rows) == r:
            return True
    return False


